SELECT id, employee_id, employee_name, id_card, phone, email, department, position, entry_date, daily_wage, salary_status, remark, tenant_id, delete_flag, create_time, update_time, creator, updater FROM jsh_salary_profile WHERE tenant_id = #{tenantId} AND delete_flag = '0'
AND employee_name LIKE CONCAT('%', #{employeeName}, '%')
AND department = #{department}
AND position LIKE CONCAT('%', #{position}, '%')
AND salary_status = #{salaryStatus}
ORDER BY create_time DESC

SELECT id, employee_id, employee_name, id_card, phone, email, department, position, entry_date, daily_wage, salary_status, remark, tenant_id, delete_flag, create_time, update_time, creator, updater FROM jsh_salary_profile WHERE tenant_id = #{tenantId} AND delete_flag = '0' AND employee_id IN
#{employeeId}
ORDER BY create_time DESC
